            addresses = { ...addresses, [target]: address };
            emit();
        },
        async book() {
            if (!isCourse && !selectedSlot)
                throw new Error("Pick a time first.");
            if (isCourse && ctaState() === "viewCourse")
                throw new Error("This course can't be booked anymore.");
            booking = true;
            error = null;
            emit();
            try {
                const result = await bookService(service, isCourse ? null : selectedSlot, formSubmissionOf(formFields, values, addresses), {
                    staffId,
                    timeZone: zoneForBooking(),
                    participants,
                    depositSelected: service.deposit?.fullUpfrontAllowed ? payDeposit : undefined,
                });
                if (result.kind === "redirect") {
                    window.location.href = result.url;
                }
                else {
                    confirmed = result;
                }
                return result;
            }
            catch (e) {
                error = e instanceof Error ? e.message : String(e);
                throw e;
            }
            finally {
                booking = false;
                emit();
            }
        },
    };
}

